```c
#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 0;
    }

    int *p = (int *)malloc(n * sizeof(int));
    if (!p) return 0;

    long long sum = 0;
    for (int i = 0; i < n; i++) {
        scanf("%d", &p[i]);
        sum += p[i];
    }

    long long avg = sum / n;

    for (int i = 0; i < n; i++) {
        printf("%lld\n", avg - p[i]);
    }

    free(p);
    return 0;
}
```

